custom_css:
/* 翩翩的你知道嗎 · 夜 · by kyuu */

/* ── 字体声明（本地优先，无网络请求） ── */
@font-face {
  font-family: 'Cormorant Garamond';
  src: local('Cormorant Garamond'), local('CormorantGaramond-Regular');
  font-weight: 400; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Cormorant Garamond';
  src: local('Cormorant Garamond Medium'), local('CormorantGaramond-Medium');
  font-weight: 500; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Cormorant Garamond';
  src: local('Cormorant Garamond SemiBold'), local('CormorantGaramond-SemiBold');
  font-weight: 600; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'Cormorant Garamond';
  src: local('Cormorant Garamond Bold'), local('CormorantGaramond-Bold');
  font-weight: 700; font-style: normal; font-display: swap;
}
@font-face {
  font-family: 'LXGW WenKai';
  src: local('LXGW WenKai'), local('LXGWWenKai-Regular');
  font-weight: 400; font-style: normal; font-display: swap;
}

/* ═══ 设计变量 ═══ */
:root {
  --frost-bg: #000000;
  --frost-chat-bg: rgba(0, 0, 0, 0.95);
  --frost-card: rgba(15, 15, 15, 0.92);
  --frost-text: #f2f2f2;
  --frost-text-secondary: #dcdcdc;
  --frost-text-muted: #aaaaaa;
  --frost-text-light: #888888;
  --frost-text-accent: #ffffff;
  --frost-quote-color: #eeeeee;
  --frost-quote-border: #666666;
  --frost-border: rgba(255, 255, 255, 0.15);
  --frost-divider: rgba(255, 255, 255, 0.08);
  --frost-input-border: #444444;
  --frost-input-focus: #999999;
  --frost-shadow-sm: 0 1px 4px rgba(0, 0, 0, 0.8);
  --frost-shadow-md: 0 3px 16px rgba(0, 0, 0, 0.9);
  --frost-focus-ring: 0 0 0 2.5px rgba(255, 255, 255, 0.2);
  --frost-radius-sm: 3px;
  --frost-radius-md: 3px;
  --frost-radius-lg: 4px;
  --frost-banner-height: 20rem;
  --frost-avatar-size: 4.5rem;
  --frost-avatar-padding-top: 7.5rem;
  --frost-card-padding-x: 1.5rem;
  --frost-header-padding-right: 5.25rem;
  --frost-btn-right: 1.5rem;
  --frost-btn-bottom: 0.95rem;
  --frost-btn-gap: 0.75rem;
  --frost-name-size: 1.125rem;
  --frost-name-spacing: 0.14em;
  --frost-body-size: 1rem;
  --frost-body-line-height: 1.85;
  --frost-blur: blur(12px);
  --frost-checkbox-checked: rgba(255, 255, 255, 0.25);
  --frost-banner-image: url('https://files.catbox.moe/h1hnu8.jpg');
  --frost-custom-text: '翩翩的你知道嗎';
  --frost-reasoning-text: '愛你的每個瞬間';
  --frost-placeholder-text: '在這個落葉像雪的季節';

  font-size: clamp(12.5px, 0.14vw + 12.4px, 18px) !important;

  /* ── SmartTheme 默认色覆盖 ── */
  --SmartThemeBodyColor: #f2f2f2;
  --SmartThemeBorderColor: rgba(255, 255, 255, 0.15);
  --SmartThemeBlurTintColor: rgba(15, 15, 15, 0.92);
  --SmartThemeChatTintColor: transparent;
  --SmartThemeQuoteColor: #eeeeee;
  --SmartThemeFastUIBGColor: rgba(15, 15, 15, 0.92);
  --SmartThemeUserMesBlurTintColor: rgba(15, 15, 15, 0.92);
  --SmartThemeBotMesBlurTintColor: rgba(15, 15, 15, 0.92);
  --SmartThemeEmColor: #dcdcdc;
  --SmartThemeShadowColor: rgba(0, 0, 0, 0.8);
}

/* ═══ 全局基础 ═══ */
body {
  background: var(--frost-bg);
  color: var(--frost-text);
  font-family: 'LXGW WenKai', 'Cormorant Garamond', serif;
  line-height: var(--frost-body-line-height);
  letter-spacing: 0.015em;
}

:is(i[class*='fa-'], .fa-solid, .fa-regular, .fa-brands) {
  font-family: 'Font Awesome 6 Free', 'FontAwesome';
}

::selection { background: rgba(255, 255, 255, 0.25); color: #ffffff; }

#chat .mes, #form_sheld, .drawer-content { box-sizing: border-box; }

/* ═══ 公共模糊 ═══ */
:is(#chat .mes, #form_sheld, #top-bar, .drawer-content, .openDrawer,
#dialogue_popup, .popup, .dialogue_popup, .select2-dropdown,
#chat .mes .mes_edit_buttons) {
  backdrop-filter: var(--frost-blur);
  -webkit-backdrop-filter: var(--frost-blur);
}

/* ═══ 聊天容器 ═══ */
#chat { background: var(--frost-chat-bg); padding: 1rem 0.5rem; }

/* ═══ 消息卡片 ═══ */
#chat .mes {
  position: relative;
  display: flex;
  flex-direction: column;
  margin: 0 auto 1.125rem;
  max-width: 94%;
  background: var(--frost-card);
  border: 1px solid var(--frost-border);
  border-radius: var(--frost-radius-md);
  box-shadow: var(--frost-shadow-sm);
  transition: box-shadow 0.28s ease;
}

#chat .mes:hover { box-shadow: var(--frost-shadow-md); }

#chat .mes::before {
  content: '';
  position: absolute;
  inset: 0 0 auto;
  height: var(--frost-banner-height);
  background:
    linear-gradient(135deg, rgba(0, 0, 0, 0.75), rgba(10, 10, 10, 0.95)),
    var(--frost-banner-image) center / cover no-repeat;
  border-radius: var(--frost-radius-md) var(--frost-radius-md) 0 0;
  mask-image: linear-gradient(to bottom, black 55%, transparent);
  -webkit-mask-image: linear-gradient(to bottom, black 55%, transparent);
  pointer-events: none;
}

/* ═══ 头像 ═══ */
#chat .mes .mesAvatarWrapper {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  padding: var(--frost-avatar-padding-top) 0 0.625rem;
  text-align: center;
}

#chat .mes .avatar {
  display: block;
  width: var(--frost-avatar-size);
  height: var(--frost-avatar-size);
  margin: 0 auto;
  flex: 0 0 auto;
  pointer-events: none;
}

#chat .mes :is(.avatar img, .mesAvatarImg) {
  width: 100%; height: 100%;
  object-fit: cover;
  border: 2px solid rgba(255, 255, 255, 0.15);
  border-radius: var(--frost-radius-md);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
  pointer-events: auto;
  transition: transform 0.28s ease;
}

#chat .mes:hover :is(.avatar img, .mesAvatarImg) { transform: scale(1.03); }

#chat .mes :is(.mesIDDisplay, .tokenCounterDisplay) {
  width: 100%;
  margin-top: 0.125rem;
  color: var(--frost-text-light);
  font: 0.75rem 'Cormorant Garamond', serif;
  letter-spacing: 0.04em;
  text-align: center;
}

/* ═══ 消息结构 ═══ */
#chat .mes .mes_block { position: relative; z-index: 1; }
#chat .mes .mes_ghost { display: none; }

/* ═══ 消息头部 ═══ */
#chat .mes .ch_name {
  position: relative;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 1.4rem var(--frost-header-padding-right) 0.875rem var(--frost-card-padding-x);
  border-bottom: 1px solid var(--frost-divider);
}

#chat .mes .ch_name > .flex-container,
#chat .mes .ch_name > .flex-container > .flex-container {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: 100%;
}

#chat .mes .name_text {
  order: 1;
  width: 100%;
  color: var(--frost-text-secondary);
  font: 600 var(--frost-name-size) 'Cormorant Garamond', 'LXGW WenKai', serif;
  letter-spacing: var(--frost-name-spacing);
  line-height: 1.2;
  text-transform: uppercase;
}

#chat .mes .ch_name::after {
  content: var(--frost-custom-text);
  display: block;
  order: 2;
  margin-top: 0.2rem;
  color: var(--frost-text-light);
  font-size: 0.906rem;
  font-style: italic;
  letter-spacing: 0.07em;
  line-height: 1.4;
  word-break: break-word;
}

#chat .mes .timestamp {
  order: 3;
  margin-top: 0.2rem;
  color: var(--frost-text-light);
  font: 0.8125rem 'Cormorant Garamond', serif;
}

#chat .mes :is(.swipe_right, .swipe_left) { transform: translateY(0.8rem); }

/* ═══ 操作按钮 ═══ */
#chat .mes :is(.mes_buttons, .mes_edit_buttons) {
  position: absolute;
  right: var(--frost-btn-right);
  bottom: var(--frost-btn-bottom);
  z-index: 20;
  display: flex;
  align-items: center;
}

#chat .mes .mes_buttons { gap: var(--frost-btn-gap); }

#chat .mes .mes_edit_buttons {
  display: none;
  gap: 0.5rem;
  padding: 0.35rem 0.6rem;
  background: var(--frost-card);
  border: 1px solid var(--frost-border);
  border-radius: var(--frost-radius-lg);
  box-shadow: var(--frost-shadow-sm);
}

#chat .mes :is(.mes_button, .extraMesButtons > div, .mes_edit_buttons > div) {
  color: var(--frost-text-muted);
  background: transparent;
  border: none;
  opacity: 0.65;
  font-size: 0.938rem;
  cursor: pointer;
  transition: color 0.15s, opacity 0.15s;
}

#chat .mes :is(.mes_button, .extraMesButtons > div, .mes_edit_buttons > div):hover {
  color: var(--frost-text-accent);
  opacity: 1;
}

#chat .mes .mes_edit_buttons :is(.mes_edit_delete, .mes_edit_cancel) { color: #999999; }
#chat .mes .mes_edit_buttons .disabled { opacity: 0.3; pointer-events: none; }

@supports selector(:has(*)) {
  #chat .mes:has(.edit_textarea:not([style*='display: none'])) .mes_buttons,
  #chat .mes:has(.edit_textarea:not([style*='display: none'])) :is(.mes_buttons > div:not(.mes_edit), .extraMesButtons) { display: none; }
  #chat .mes:has(.edit_textarea:not([style*='display: none'])) .mes_edit_buttons { display: flex; }
}

/* ═══ 正文排版 ═══ */
#chat .mes .mes_text {
  padding: 1rem var(--frost-card-padding-x) 1.25rem;
  color: var(--frost-text);
  font-size: var(--frost-body-size);
  text-align: justify;
}

#chat .mes .mes_text p { margin-bottom: 0.5em; }
#chat .mes .mes_text p > br:first-child,
#chat .mes .mes_text p * > br:first-child { display: none; }
#chat .mes .mes_text :is(em, i) { color: var(--frost-text-secondary); }
#chat .mes .mes_text :is(b, strong) { color: var(--frost-text-accent); font-weight: 600; }

#chat .mes .mes_text :is(blockquote, q) {
  padding-left: 0.875rem;
  border-left: 2.5px solid var(--frost-quote-border);
  color: var(--frost-quote-color);
}

#chat .mes .mes_text q { padding: 0.1rem 0.5rem; background: rgba(255, 255, 255, 0.05); border-radius: 2px; }

#chat .mes code {
  padding: 0.125rem 0.438rem;
  background: rgba(255, 255, 255, 0.1);
  border-radius: var(--frost-radius-md);
  color: var(--frost-text);
}

#chat .mes pre {
  overflow-x: auto;
  background: rgba(10, 10, 10, 0.8);
  border: 1px solid var(--frost-border);
  border-radius: var(--frost-radius-lg);
}

#chat .mes pre code { background: transparent; }

/* ═══ 编辑区域 ═══ */
:is(#curEditTextarea, .edit_textarea, .reasoning_edit_textarea) {
  width: 100%;
  min-height: 6rem;
  margin-top: 0.6rem;
  padding: 0.72rem;
  box-sizing: border-box;
  background: rgba(25, 25, 25, 0.9);
  border: 1px solid var(--frost-divider);
  border-radius: var(--frost-radius-lg);
  color: var(--frost-text);
  font-family: 'LXGW WenKai', serif;
}

/* ═══ 推理区块 ═══ */
#chat .mes_reasoning_arrow { display: none; }

#chat .mes_reasoning_header {
  margin: 0.3rem 0.5rem;
  padding: 0.5rem 0.875rem;
  background: rgba(25, 25, 25, 0.6);
  border-radius: var(--frost-radius-md);
}

#chat .mes_reasoning_header .mes_reasoning_header_title { font-size: 0; }

#chat .mes_reasoning_header .mes_reasoning_header_title::before {
  content: var(--frost-reasoning-text);
  color: #777777;
  font: 0.69rem 'Cormorant Garamond', serif;
  letter-spacing: 0.14em;
}

#chat .mes_reasoning {
  padding: 0.72rem 1.08rem;
  border-top: 1px dashed var(--frost-input-border);
  color: var(--frost-text-muted);
  font-size: 0.81rem;
}

/* ═══ 输入区域 ═══ */
#form_sheld {
  background: #000000;
  border-top: 1px solid var(--frost-border);
}

#send_form { padding: 0.05rem 0.95rem; }
#nonQRFormItems { position: relative; }

#send_textarea {
  flex-grow: 1;
  min-height: 1.72rem;
  padding: 0.625rem 0.25rem;
  background: transparent;
  border: 0;
  outline: none;
  color: var(--frost-text);
  font-size: 0.875rem;
  line-height: 1.3;
  resize: none;
}

@supports selector(:has(*)) {
  #nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: var(--frost-placeholder-text);
    position: absolute;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    max-width: 80%;
    color: #777777;
    font: italic 0.95rem 'LXGW WenKai', serif;
    pointer-events: none;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  #send_textarea::placeholder { opacity: 0; }
}

@supports not selector(:has(*)) {
  #send_textarea::placeholder {
    color: #777777;
    font: italic 0.81rem 'LXGW WenKai', serif;
  }
}

/* ═══ 顶栏与图标 ═══ */
#top-bar {
  background: var(--frost-card);
  border-bottom: 1px solid var(--frost-border);
}

:is(#top-settings-holder .drawer-icon,
#rightSendForm > div:not(.stscript_btn):not(.mes_stop),
#leftSendForm > div) {
  color: var(--frost-text-secondary);
  transition: color 0.15s;
}

:is(#top-settings-holder .drawer-icon,
#rightSendForm > div:not(.stscript_btn):not(.mes_stop),
#leftSendForm > div):hover {
  color: var(--frost-text-accent);
}

/* ═══ 表单控件 ═══ */
:is(.text_pole,
.drawer-content input:not([type='checkbox']):not([type='range']),
.drawer-content select,
.drawer-content textarea) {
  padding: 0.48rem 0.72rem;
  background: rgba(25, 25, 25, 0.9);
  border: 1px solid var(--frost-input-border);
  border-radius: var(--frost-radius-lg);
  color: var(--frost-text);
  transition: background 0.15s, border-color 0.15s, box-shadow 0.15s;
}

:is(.text_pole,
.drawer-content input:not([type='checkbox']):not([type='range']),
.drawer-content select,
.drawer-content textarea):focus {
  background: #000000;
  border-color: var(--frost-input-focus);
  box-shadow: var(--frost-focus-ring);
  outline: none;
}

:is(select, option) { background: rgba(20, 20, 20, 0.95); color: var(--frost-text); }

/* Select2 */
:is(.select2-container--default .select2-selection,
.select2-container .select2-selection--single,
.select2-container .select2-selection--multiple) {
  background: rgba(25, 25, 25, 0.9);
  border: 1px solid var(--frost-input-border);
  border-radius: var(--frost-radius-lg);
}

.select2-container--default .select2-selection--multiple .select2-selection__choice {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid var(--frost-border);
  border-radius: var(--frost-radius-sm);
}

.select2-dropdown {
  background: rgba(15, 15, 15, 0.95);
  border: 1px solid var(--frost-input-border);
  border-radius: var(--frost-radius-lg);
  box-shadow: var(--frost-shadow-md);
}

.select2-container--default .select2-results__option--highlighted[aria-selected] { background: rgba(255, 255, 255, 0.15); }
.select2-container--default .select2-results__option--selected { background: rgba(255, 255, 255, 0.08); }

/* 复选框 */
input[type='checkbox'] {
  width: 1.0625rem; height: 1.0625rem;
  margin-right: 0.42rem;
  vertical-align: middle;
  appearance: none;
  background: rgba(0, 0, 0, 0.8);
  border: 1.5px solid rgba(255, 255, 255, 0.4);
  border-radius: var(--frost-radius-md);
  cursor: pointer;
}

input[type='checkbox']:checked {
  background:
    var(--frost-checkbox-checked)
    url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='white'%3e%3cpath d='M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z'/%3e%3c/svg%3e")
    center / 75% no-repeat;
  border-color: var(--frost-text-accent);
}

/* 滑动条 */
:is(input[type='range'], .neo-range-slider),
:is(input[type='range'], .neo-range-slider):disabled {
  height: 1.3rem;
  appearance: none;
  background: transparent !important;
  outline: none;
  opacity: 1 !important;
  filter: none !important;
  cursor: pointer;
}

:is(input[type='range'], .neo-range-slider)::-webkit-slider-runnable-track,
:is(input[type='range'], .neo-range-slider):disabled::-webkit-slider-runnable-track {
  height: 4px;
  background: #444444 !important;
  border-radius: 999px;
}

:is(input[type='range'], .neo-range-slider)::-webkit-slider-thumb,
:is(input[type='range'], .neo-range-slider):disabled::-webkit-slider-thumb {
  width: 0.95rem; height: 0.95rem;
  margin-top: -0.34rem;
  appearance: none;
  background: var(--frost-text-accent) !important;
  border: 2px solid #555555 !important;
  border-radius: 50%;
  box-shadow: 0 0 6px rgba(0, 0, 0, 0.4);
}

:is(input[type='range'], .neo-range-slider):active::-webkit-slider-thumb {
  background: #cccccc !important;
}

/* ═══ 滚动条 ═══ */
:is(body, #chat, .scrollableInner, .drawer-content, .inline-drawer-content, .mes_text, textarea, select, pre) {
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) transparent;
}

::-webkit-scrollbar { width: 7px; height: 7px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border: 1.5px solid transparent;
  border-radius: 999px;
  background-clip: content-box;
}
::-webkit-scrollbar-thumb:hover { background: rgba(255, 255, 255, 0.35); }

/* ═══ 面板与抽屉 ═══ */
:is(.drawer-content, .openDrawer, #dialogue_popup, #dialogue_popup_text, .popup, .dialogue_popup) {
  background: rgba(15, 15, 15, 0.95);
  border: 1px solid var(--frost-border);
  box-shadow: var(--frost-shadow-md);
  color: var(--frost-text);
}

:is(.inline-drawer, .inline-drawer-content) {
  background: transparent;
  border: 0;
  box-shadow: none;
  color: var(--frost-text);
}

.drawer-content :is(span, label, p, div, small, .checkbox_label, .range-block-title, [data-i18n]) {
  color: var(--frost-text);
}

#top-settings-holder :is(
  .inline-drawer-header, .inline-drawer-toggle, .wide_toggle,
  .stscript_btn, .panel-heading, .menu_button.wide, h3, h4) {
  background: rgba(30, 30, 30, 0.8);
  border: 1px solid var(--frost-border);
  border-radius: var(--frost-radius-md);
  color: var(--frost-text);
}

#top-settings-holder :is(
  .inline-drawer-header, .inline-drawer-toggle, .wide_toggle,
  .stscript_btn, .panel-heading, .menu_button.wide):hover {
  background: rgba(50, 50, 50, 0.9);
  color: #ffffff;
}

#shadow_popup { background: rgba(0, 0, 0, 0.28); }

:is(h4, .title_restorable) {
  background: rgba(30, 30, 30, 0.8);
  border-radius: var(--frost-radius-sm);
  color: var(--frost-text);
}

/* ═══ 世界信息 ═══ */
:is(#WorldInfo, #world_info_panel),
:is(#WorldInfo, #world_info_panel) :is(
  .inline-drawer, .inline-drawer-content, .inline-drawer-header,
  .inline-drawer-toggle,
  .world_entry, .world_entry_form, .world_entry_block,
  .world_entry_fields, .world_entry_content, .range-block,
  .text_pole_label, .checkbox_label, .checkbox-container,
  .checkbox_control, .form-control, .switch, .toggle-button,
  .select2-container .select2-selection,
  .select2-container .select2-selection--single,
  .select2-container .select2-selection--multiple,
  .select2-search__field, .text_pole) {
  background: transparent;
  border: 0;
  box-shadow: none;
}

:is(#WorldInfo, #world_info_panel) .world_entry {
  padding-bottom: 0.45rem;
  border-bottom: 1px solid var(--frost-divider);
  opacity: 0.85;
  transition: opacity 0.2s;
}

:is(#WorldInfo, #world_info_panel) :is(.world_entry:hover, .active-world-info) { opacity: 1; }

:is(#WorldInfo, #world_info_panel) .inline-drawer-toggle {
  background: transparent;
  border: 0;
}

/* ═══ 补充默认色覆盖 ═══ */
a, a:visited, a:active { color: var(--frost-text-muted) !important; text-decoration: none !important; }
a:hover { color: var(--frost-text-accent) !important; }

:is(.menu_button, #options_button, #extensionsMenuButton,
.mes_stop, #dialogue_del_mes, #rightSendForm > div,
#leftSendForm > div) {
  color: var(--frost-text-muted) !important;
}

:is(.list-group-item, .ctx-item, .ctx-header, .ctx-menu) {
  color: var(--frost-text) !important;
  background: rgba(15, 15, 15, 0.95) !important;
}
:is(.list-group-item, .ctx-item):hover {
  background: rgba(50, 50, 50, 0.9) !important;
}

.mes_stop {
  background: rgba(15, 15, 15, 0.92) !important;
  border-color: var(--frost-border) !important;
}

/* ═══ 气泡模式欢迎面板 ═══ */
body.bubblechat .welcomePanel {
  border-radius: 10px;
  background-color: rgb(12 12 12 / 90%);
  border: 1px solid var(--frost-border);
  margin-bottom: 5px;
}

/* ═══ 禁用状态 ═══ */
#completion_prompt_manager #completion_prompt_manager_list
  .completion_prompt_manager_prompt_disabled
  :is(.completion_prompt_manager_prompt_name, .completion_prompt_manager_prompt_name .prompt-manager-inspect-action) {
  color: var(--frost-text-muted);
}

:is(input:not([type='range']), textarea):disabled {
  filter: none;
  background-color: rgba(30, 30, 30, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 2px 1px rgba(0, 0, 0, 0.4);
  color: var(--frost-text-muted);
  cursor: not-allowed;
  opacity: 0.85;
}

.text_pole[type="number"][style*="calc(3em"] {
  min-width: calc(5em + 15px);
  padding-inline: 0.36rem;
  font-variant-numeric: tabular-nums;
}

/* ═══ 移动端 ═══ */
@media screen and (max-width: 768px) {
  #chat { padding: 0.4rem 0.15rem; }
  #chat .mes { max-width: 98%; margin: 0 auto 0.72rem; }
  #chat .mes::before { height: calc(var(--frost-banner-height) * 0.72); }
  #chat .mes .mesAvatarWrapper { padding-top: calc(var(--frost-avatar-padding-top) * 0.65); }
  #chat .mes .ch_name { padding-right: var(--frost-card-padding-x); padding-left: var(--frost-card-padding-x); }
  #chat .mes .mes_text { padding: 0.9rem var(--frost-card-padding-x); text-align: start; }
  #chat .mes .mes_buttons { gap: calc(var(--frost-btn-gap) * 0.8); }
  #send_form { padding: 0.12rem 0.55rem; }
}
